/* Interactive design only. No API, capture, authentication or publication occurs. */
'use strict';
const $ = (q, root = document) => root.querySelector(q);
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name = 'grid') => { const paths = {grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',archive:'M3 4h18v5H3z M5 9v12h14V9 M9 13h6',plus:'M12 5v14 M5 12h14',queue:'M4 6h16 M4 12h16 M4 18h10',source:'M5 3v18 M5 6h10a5 5 0 0 1 0 10H5',compare:'M4 4h6v16H4z M14 4h6v16h-6z',note:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',search:'M10 3a7 7 0 1 0 0 14a7 7 0 0 0 0-14 M15 15l6 6',watch:'M12 4a8 8 0 1 0 0 16a8 8 0 0 0 0-16 M12 7v5l3 2',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',share:'M8 7l8-3 M8 9l8 9 M4 5h4v5H4z M16 2h4v5h-4z M16 17h4v5h-4z'}; return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name] || paths.grid}"/></svg>`; };
const stages = ['V0 · controlled pilot','1.0 · production preservation','1.1 · comparison / context / B0','1.2 · attention / search / B1','1.3 · reports / transfer / U1','1.4 · watches / B2','1.5 · delivery / access spaces','1.6 · federation / workloads'];
const model = {stage:0, role:'admin', state:'ready', tab:'evidence', approved:false, revision:7, publishedRevision:null, important:true, submitted:false, published:false, acknowledged:false, collection:'Riverfront review', note:'Compare the review period against the earlier notice. This is an editorial assertion, not captured source text.', tags:'procurement, public-records'};
const query = new URLSearchParams(location.search);
if (query.has('stage')) model.stage = Math.min(7,Math.max(0,Number(query.get('stage')) || 0));
if (query.get('role') === 'editor') model.role = 'editor';
if (query.get('theme') === 'dark') document.body.classList.add('dark');
const screens = {
 dashboard:{name:'Overview',icon:'grid',stage:0,states:['ready','empty','loading','offline'],ref:'06, 16, 28'},
 archive:{name:'Evidence archive',icon:'archive',stage:0,states:['ready','empty','loading','denied'],ref:'06, 16, 21, 28, 40'},
 capture:{name:'Capture detail',icon:'archive',stage:0,states:['ready','partial','failed','conflict','denied'],ref:'15, 16, 28, 40, 52'},
 new:{name:'New capture',icon:'plus',stage:0,states:['ready','invalid','queue-full','offline'],ref:'04, 14, 16, 28, 42'},
 batch:{name:'CSV intake',icon:'plus',stage:0,states:['ready','preview','stale','queue-full'],ref:'04, 14, 16, 28'},
 queue:{name:'Capture queue',icon:'queue',stage:0,states:['ready','empty','reconnecting','failed'],ref:'04, 14, 42'},
 source:{name:'Source history',icon:'source',stage:0,states:['ready','empty','failed'],ref:'21, 28, 40'},
 publication:{name:'Publication preview',icon:'share',stage:0,states:['ready','revoked','denied'],ref:'07, 15, 16, 52'},
 public:{name:'Public evidence viewer',icon:'share',stage:0,states:['ready','revoked','unavailable'],ref:'07, 15, 52'},
 export:{name:'Private export',icon:'archive',stage:0,states:['ready','queued','failed','expired'],ref:'05, 15, 40, 51, 52'},
 settings:{name:'Workspace settings',icon:'settings',stage:0,states:['ready','degraded','denied'],ref:'44–49'},
 admission:{name:'Sign-in & admission',icon:'settings',stage:0,states:['ready','denied','expired','provider-error'],ref:'07, 16, 48'},
 compare:{name:'Compare captures',icon:'compare',stage:2,states:['ready','unsupported','identical','failed'],ref:'21, 40, 41'},
 investigation:{name:'Investigation context',icon:'note',stage:2,states:['ready','stale-anchor','conflict'],ref:'28, 29, 41'},
 attention:{name:'Attention inbox',icon:'note',stage:3,states:['ready','empty','failed'],ref:'22, 28'},
 profiles:{name:'Comparison profiles',icon:'settings',stage:3,states:['ready','invalid','failed'],ref:'22, 27'},
 search:{name:'Search & research cues',icon:'search',stage:3,states:['ready','no-hits','no-coverage'],ref:'30, 40'},
 reports:{name:'Investigation report',icon:'note',stage:4,states:['ready','missing-input','failed'],ref:'31, 41'},
 transfer:{name:'Native case transfer',icon:'archive',stage:4,states:['ready','quarantined','denied'],ref:'32, 41'},
 watches:{name:'Watch management',icon:'watch',stage:5,states:['ready','paused','quota','restore-hold'],ref:'23, 42'},
 delivery:{name:'Notification delivery',icon:'share',stage:6,states:['ready','uncertain','expired','denied'],ref:'24, 42'},
 pairing:{name:'Companion pairing',icon:'settings',stage:2,states:['ready','approved','expired','denied'],ref:'34, 35, 37'},
 access:{name:'Users & access spaces',icon:'settings',stage:6,states:['ready','denied','conflict'],ref:'48, 49'}
};
let screen = location.hash.slice(1) || 'dashboard';
if (!screens[screen]) screen = 'dashboard';
model.stage = Math.max(model.stage,screens[screen].stage);
if (screens[screen].states.includes(query.get('state'))) model.state = query.get('state');
const pill=(text,kind='')=>`<span class="pill ${kind}">${esc(text)}</span>`;
const btn=(label,action,kind='',attrs='')=>`<button type="button" class="${kind}" data-action="${action}" ${attrs}>${label}</button>`;
const go=(label,target,kind='')=>`<a class="${kind}" href="#${target}">${label}</a>`;
const notice=(title,body,kind='')=>`<div class="notice ${kind}"><strong>${title}</strong>${body}</div>`;
const card=(title,body,extra='')=>`<section class="card"><div class="card-head"><h2>${title}</h2>${extra}</div><div class="pad">${body}</div></section>`;
const head=(kicker,title,sub,actions='')=>`<div class="page-head"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><div class="sub">${sub}</div></div><div class="flex">${actions}</div></div>`;
const check=(text,detail='',checked=false,attrs='')=>`<label class="checkline"><input type="checkbox" ${checked?'checked':''} ${attrs}><span>${text}${detail?`<small>${detail}</small>`:''}</span></label>`;
const field=(label,input,hint='')=>`<label class="field">${label}${input}${hint?`<small>${hint}</small>`:''}</label>`;
const kv=rows=>`<dl class="kv">${rows.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;
const empty=(title,body,action='')=>`<div class="card empty"><div class="empty-symbol">◌</div><h2>${title}</h2><p>${body}</p>${action}</div>`;
const fixtureRows = [
 ['Riverfront contract enters a second review period','news.example.org/city/riverfront','09 Nov · 10:43 UTC','Complete','Needs review','Server capture'],
 ['City notice register · original announcement','records.example.org/notices/1042','08 Nov · 15:18 UTC','Complete','Approved','Server capture'],
 ['Committee agenda and supporting documents','council.example.org/agenda/november','08 Nov · 09:06 UTC','Partial','Needs review','Server capture'],
 ['Budget annex · attempted acquisition','records.example.org/budget/annex','07 Nov · 11:22 UTC','Failed','Unavailable','Server capture']
];
function tableRows(rows=fixtureRows,compact=false){return `<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable evidence table"><table><thead><tr><th>Evidence / source</th><th>Captured at ↓</th><th>Acquisition</th>${compact?'':'<th>Review</th><th>Visibility</th>'}</tr></thead><tbody>${rows.map((r,i)=>`<tr><td><div class="capture-strip"><span class="preview-mini">${i<3?'<img src="source-preview.svg" alt="">':'—'}</span><div class="text"><a class="title" href="#capture">${esc(r[0])}</a><small>${esc(r[1])}</small><div class="spaced" style="margin-top:5px">${i===0&&model.important?pill('Important','warn'):''} <span class="chip">Riverfront review</span></div></div></div></td><td>${r[2]}<br><small>${r[5]}</small></td><td>${pill(r[3],r[3]==='Complete'?'good':r[3]==='Partial'?'warn':'bad')}</td>${compact?'':`<td>${pill(r[4],r[4]==='Approved'?'teal':'')}</td><td>${pill('Private')}</td>`}</tr>`).join('')}</tbody></table></div>`;}
function route(next){if(!screens[next])return;screen=next;model.state='ready';model.tab='evidence';const min=screens[next].stage;if(model.stage<min){model.stage=min;toast(`Previewing ${stages[min]}. Future feature; not part of V0.`);}location.hash=next;render();}
function toast(message){const box=$('#toast');box.textContent=message;box.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.classList.remove('show'),4500);}
let dialogTrigger;
function modal(title,body,action,label){dialogTrigger=document.activeElement;$('#dialog-content').innerHTML=`<h2>${title}</h2>${body}<div class="dialog-actions">${btn('Cancel','close')}${btn(label,action,'primary')}</div>`;$('#dialog').showModal();}
function closeModal(){ $('#dialog').close();dialogTrigger?.focus(); }
function stateNotice(){const s=model.state;if(s==='offline')return notice('Connection unavailable','Your draft remains in this local design session. A real client must confirm server acceptance before reporting a queued capture.','warn');if(s==='failed')return notice('Operation failed','No successful result is inferred. Inspect the last confirmed state and retry deliberately under current authority.','bad');if(s==='loading')return '<div class="notice" role="status">Loading records… No totals are inferred while data is unavailable.</div>';if(s==='conflict')return notice('A newer revision exists','Your edits have not replaced the latest version. Compare changes, reload the current revision and apply your intent again.','warn');return '';}
function render(){
 const meta=screens[screen];
 const core=['dashboard','archive','new','batch','queue','source'];
 const later=['compare','investigation','attention','profiles','search','reports','transfer','watches','delivery','pairing','access'];
 const navItem=id=>`<a class="nav-item ${id===screen?'active':''}" href="#${id}" ${id===screen?'aria-current="page"':''}>${icon(screens[id].icon)}${screens[id].name}${screens[id].stage?`<span class="count">${stages[screens[id].stage].split(' ·')[0]}</span>`:id==='queue'?'<span class="count">3</span>':''}</a>`;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">e.</div><div><b>Evidence Workspace</b><small>Provereno / newsroom</small></div>${btn('Menu','menu','mobile-nav small','aria-expanded="false"')}</div><div class="nav-group"><div class="nav-label">Workspace · private</div>${core.map(navItem).join('')}<div class="nav-label">Later design previews</div><details class="nav-preview" ${model.stage>=2?'open':''}><summary>Browse future screens</summary>${later.map(navItem).join('')}</details><div class="nav-label">Administration</div>${navItem('settings')}${navItem('admission')}</div><div class="sidebar-foot"><div class="user"><span class="avatar">AM</span><div><b>Alex Morgan</b>Synthetic ${model.role}</div></div><p class="spaced">Collections organize evidence.<br>V0 is one shared newsroom.</p><a href="../docs/requirements/54-ui-blueprints-and-interaction-map.md">UI specification ↗</a></div></aside><div class="body-area"><header class="topbar"><span class="crumb">Newsroom <span aria-hidden="true">/</span> ${meta.name}</span><div class="controls"><label>Target<select id="stage" aria-label="Design release target">${stages.map((s,i)=>`<option value="${i}" ${i===model.stage?'selected':''}>${s}</option>`).join('')}</select></label><label>Role<select id="role" aria-label="Simulated V0 role"><option ${model.role==='admin'?'selected':''}>admin</option><option ${model.role==='editor'?'selected':''}>editor</option></select></label><label>State<select id="state" aria-label="Screen state">${meta.states.map(s=>`<option ${s===model.state?'selected':''}>${s}</option>`).join('')}</select></label></div></header><main id="main" tabindex="-1">${model.stage?`<div class="version-preview">DESIGN TARGET: ${esc(stages[model.stage])} · staged capabilities require independent qualification and enablement.</div>`:''}${stateNotice()}${renderScreen()}<div class="screen-reference">${screen.toUpperCase()} · Requirements documents ${meta.ref} · Synthetic design; not evidence of implemented permissions, integrity or runtime behavior.<br>Use the state and role controls to inspect alternatives. <a href="../docs/requirements/55-versioned-implementation-plan.md">Versioned delivery plan ↗</a></div></main></div></div>`;
 $('#theme').textContent=document.body.classList.contains('dark')?'Light theme':'Dark theme';
}
function renderScreen(){
 if(model.state==='denied')return head('Access boundary',screens[screen].name,'Permissions are checked again by the server on every route and artifact request.')+empty('Access unavailable','This identity cannot access this resource. No title, count, file path or private metadata is disclosed.',go('Return to overview','dashboard'));
 switch(screen){
 case 'dashboard':return dashboard();
 case 'archive':return archive();
 case 'new':return newCapture();
 case 'batch':return batch();
 case 'queue':return queue();
 case 'capture':return detail();
 case 'source':return source();
 case 'publication':return publication();
 case 'public':return publicViewer();
 case 'export':return exportScreen();
 case 'settings':return settings();
 case 'admission':return admission();
 case 'compare':return compare();
 case 'investigation':return investigation();
 case 'attention':return attention();
 case 'profiles':return profiles();
 case 'search':return search();
 case 'reports':return reports();
 case 'transfer':return transfer();
 case 'watches':return watches();
 case 'delivery':return delivery();
 case 'pairing':return pairing();
 case 'access':return access();
 }
}
function dashboard(){return head('Newsroom / 09 November 2026','A record you can return to.','Capture the source, preserve its context, and decide what can be shared.',btn('+ Capture a page','new','primary'))+(model.state==='empty'?empty('Start with a source','Evidence is private until an administrator explicitly publishes a reviewed projection.',btn('Create the first capture','new','primary')):`<div class="grid four"><div class="card stat"><span>PRIVATE CAPTURES</span><strong>128</strong><small>116 complete · 9 partial · 3 failed</small></div><div class="card stat"><span>NEEDS REVIEW</span><strong>14</strong><small>Editorial approval is revision specific</small></div><div class="card stat"><span>ACTIVE JOBS</span><strong>${model.submitted?'4':'3'}</strong><small>1 capturing · 2 waiting${model.submitted?' · 1 new':''}</small></div><div class="card stat"><span>PUBLIC PROJECTIONS</span><strong>${model.published?'7':'6'}</strong><small>Explicit publication · administrator only</small></div></div><div class="grid cols spaced"><section class="card"><div class="card-head"><h2>Recent evidence</h2>${go('Open archive →','archive')}</div>${tableRows(fixtureRows.slice(0,3),true)}</section><div class="stack">${card('Continue the investigation',`<p class="eyebrow">Collection / Riverfront review</p><p>Three attempts preserve the changing public notice. Keep findings separate from what the source actually said.</p>${go('Inspect source history →','source')}`)}${card('System pulse',`${kv([['Capture worker',pill('Available','good')],['Queue capacity','3 / 1,000 pending'],['Artifact storage','18.4 GiB free'],['Last backup','Synthetic status · 02:00 UTC']])}<hr class="divider">${go('Operator status →','settings')}`)}</div></div>`);}
function archive(){return head('Evidence / 128 records','Evidence archive','Captured bytes remain immutable. Notes, collections and review are a separate editorial layer.',btn('New capture','new','primary'))+`<div class="toolbar"><div class="search">${icon('search')}<input id="archive-search" aria-label="Filter synthetic evidence by title or URL" placeholder="Filter by title or URL…"></div><select id="archive-filter" aria-label="Importance filter"><option value="all">All importance</option><option value="important">Important only</option></select><select aria-label="Collection filter"><option>Riverfront review</option><option>All collections</option></select>${btn('Reset filters','reset-filters','small')}</div>`+(model.state==='empty'?empty('No evidence matches','Clear a filter or start a capture. An empty list does not mean records were deleted.',btn('Reset filters','reset-filters')):`<div class="card" id="archive-table">${tableRows()}</div><div class="footer-note"><span>4 synthetic rows shown · default order: captured_at, then ID</span><span>Page 1 of 6 · 25 per page</span></div>`);}
function newCapture(){return head('Acquisition / server browser','Capture a web page','The server visits the submitted public URL. It does not inherit your browser login or cookies.')+`<div class="grid cols"><form id="capture-form" class="card pad"><div class="flow-steps"><span class="active">01 / Source & context</span><span>02 / Queue</span><span>03 / Evidence</span></div>${model.state==='invalid'?notice('Check the source URL','Enter a public HTTP(S) URL. Credentials, local destinations and unsupported schemes are rejected.','bad'):''}${model.state==='queue-full'?notice('The capture queue is full','Nothing was submitted. Keep your draft and retry after capacity becomes available.','warn'):''}${field('Public URL <span aria-hidden="true">*</span>','<input id="capture-url" type="url" required value="https://news.example.org/city/riverfront" placeholder="https://example.org/article">','The original submitted URL is retained. Server network policy is applied to redirects and subresources.')}${field('Collection','<select id="capture-collection"><option>Riverfront review</option><option>Uncollected</option></select>','A collection is a grouping, not an access boundary in V0.')}${field('Why capture this source?','<textarea id="capture-rationale" maxlength="2048">Preserve the revised review period before the next committee meeting.</textarea>','Optional · private request context · maximum 2,048 characters · excluded from default public/export output.')}${check('Mark important','Shared editorial triage; does not approve, acknowledge or publish.',true,'id="new-important"')}<hr class="divider"><div class="flex between">${pill('Private by default','teal')}<button class="primary" type="submit">Queue capture →</button></div></form>${card('What will be preserved',`${kv([['Capture profile',model.stage?'workspace-capture-production/1 · new qualified attempts':'workspace-capture-v0/1'],['Required',model.stage?'PNG, MHTML, network WARC, capture/recording metadata and manifest':'Screenshot PNG, page MHTML, metadata and manifest'],['WARC',model.stage?'New production attempts require a qualified production profile.':'Not produced by the V0 profile'],['Time','Server-observed capture time; no trusted timestamp claim'],['Outcome','Complete, partial, failed or cancelled — shown explicitly']])}<hr class="divider"><p class="muted">This mockup queues a synthetic job only. No URL is fetched.</p>` )}</div>`;}
function batch(){const preview=model.state!=='ready';return head('Acquisition / bulk intake','Review a CSV before queuing','Previewing never creates jobs. Confirm the complete accepted selection once capacity is available.')+`<div class="flow-steps"><span class="${!preview?'active':''}">01 / Select CSV</span><span class="${preview?'active':''}">02 / Review rows</span><span>03 / Confirm queue</span></div>${model.state==='stale'?notice('Preview expired','No jobs were created. Generate a new actor-bound preview before confirmation.','warn'):model.state==='queue-full'?notice('Not enough queue positions','The selected batch is admitted atomically. No subset has been silently queued.','warn'):''}<div class="grid cols"><div class="stack"><div class="card pad"><div class="upload-area"><b>sources.csv</b><p class="spaced">Synthetic CSV fixture · 4 rows · 1.2 KiB</p>${btn(preview?'Regenerate preview':'Preview synthetic CSV','csv-preview','primary')}<p class="spaced muted">Production picker: UTF-8 CSV · ≤1 MiB · ≤500 rows.</p></div></div>${preview?`<section class="card"><div class="card-head"><h2>Row validation</h2>${pill('2 ready · 1 duplicate · 1 invalid','warn')}</div><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable evidence table"><table><thead><tr><th>Row / URL</th><th>Disposition</th></tr></thead><tbody><tr><td>2 · news.example.org/city/riverfront</td><td>${pill('Ready','good')}</td></tr><tr><td>3 · records.example.org/notices/1042</td><td>${pill('Duplicate','warn')}<br>Explicit choice: skip</td></tr><tr><td>4 · council.example.org/agenda/november</td><td>${pill('Ready','good')}</td></tr><tr><td>5 · invalid URL</td><td>${pill('Rejected','bad')}<br>Excluded; correction required</td></tr></tbody></table></div><div class="pad flex between"><span class="muted">2 selected rows · duplicate skipped</span>${btn('Confirm 2 capture intents','csv-confirm','primary',model.state==='stale'?'disabled':'')}</div></section>`:''}</div>${card('Shared submission context',`${field('Collection','<select><option>Riverfront review</option></select>')}${field('Rationale','<textarea maxlength="2048">Preserve source material cited in the committee notice.</textarea>')}${check('Important','Applied to the new records; independent of review.')}<p class="muted">Submitted context is frozen with each intent. Later editorial edits are not overwritten by a worker.</p>`)}</div>`;}
function queue(){return head('Execution / durable state','Capture queue','Waiting and attempt states come from the server. A running job has no invented percentage.',btn('New capture','new','primary'))+(model.state==='reconnecting'?notice('Reconnecting to updates','Showing the last confirmed state. The client must reconcile durable sequence IDs after reconnecting.','warn'):'')+(model.state==='empty'?empty('The queue is clear','New captures will appear here after server admission.',btn('Capture a page','new','primary')):`<div class="card"><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable evidence table"><table><thead><tr><th>Job / submitted source</th><th>State</th><th>Attempt</th><th>Actions</th></tr></thead><tbody>${[[model.submitted?'New request · Riverfront notice':'Riverfront notice',model.state==='failed'?'Failed':'Capturing','1 of 3'],['City procurement register','Queued','Not started'],['Committee agenda','Queued','Not started']].map((r,i)=>`<tr><td><a class="title" href="#capture">${r[0]}</a><small>Requested 09 Nov · 10:42 UTC · Riverfront review</small></td><td>${pill(r[1],r[1]==='Failed'?'bad':i===0?'teal':'')}<br><small>${i===0?'Last confirmed heartbeat: just now':'Waiting for the shared heavy-work permit'}</small></td><td>${r[2]}</td><td>${btn(r[1]==='Failed'?'Retry as a new attempt':'Cancel request',r[1]==='Failed'?'retry-job':'cancel-job','small')}</td></tr>`).join('')}</tbody></table></div></div>${card('Job detail / capture-0128',`${kv([['Current phase',model.state==='failed'?'Navigation failed':'Browser navigation and readiness'],['Deadline','120 seconds per attempt'],['Lease','Server-owned generation; stale workers cannot commit'],['Retry policy','Up to 3 attempts; bounded delay and reason'],['Cancellation','Requested → worker observes fence → cancelled; late bytes discarded']])}<hr class="divider"><p class="muted">A retry preserves the failed attempt in Source history. Refreshing this screen never creates a new attempt.</p>`)}<div class="footer-note">Queue-full responses preserve the draft; they do not claim an accepted job.</div>`);}
function detail(){if(model.state==='failed')return head('Capture / cap-0128','Acquisition did not complete','The failed attempt remains in Source history; there are no complete evidence bytes to open.')+notice('Navigation timeout','The runner reached its deadline. Failure is operational evidence of an attempt, not proof that the source was deleted.','bad')+card('Attempt record',`${kv([['Profile','workspace-capture-v0/1'],['Requested URL','https://news.example.org/city/riverfront'],['State','Failed · no complete artifact set'],['Attempt','1 of 3']])}<hr class="divider">${btn('Retry as a new attempt','retry-job','primary')} ${go('Source history','source')}`);
 const tab=model.tab;return head('Capture / cap-0128', 'Riverfront contract enters a second review period',`<span class="url">news.example.org/city/riverfront</span> · server observed 09 Nov 2026, 10:43:12 UTC`,`${btn(model.important?'★ Important':'☆ Mark important','importance','small')}${btn('Export','export','small')}${btn('Publication','publication','small')}`)+(model.state==='partial'?notice('Partial capture · required output missing','The screenshot exists, but MHTML failed validation. The record is retained; export/publication eligibility must be evaluated for the requested purpose.','warn'):'')+`<div class="flex" style="margin-bottom:20px">${pill('Private','teal')}${pill(model.state==='partial'?'Partial':'Complete',model.state==='partial'?'warn':'good')}${pill((model.approved?'Approved · revision ':'Needs review · revision ')+model.revision,model.approved?'teal':'')}${pill('Server capture')}${pill('SHA-256 recorded')}</div><div class="grid cols"><div class="card"><div class="pad" style="padding-bottom:0"><div class="tabs" role="tablist" aria-label="Capture detail tabs">${['evidence','provenance','artifacts','history'].map(t=>`<button role="tab" aria-selected="${tab===t}" class="${tab===t?'active':''}" data-action="tab-${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div></div><div role="tabpanel">${tab==='evidence'?`<div class="image-frame"><img class="evidence-image" src="source-preview.svg" alt="Synthetic captured news page: Riverfront contract enters a second review period"></div><div class="pad"><div class="flex between"><span class="muted">Screenshot · 960 × 680 · static image</span>${go('All attempts for this source →','source')}</div></div>`:tab==='provenance'?`<div class="pad">${kv([['Capture ID','cap-0128 · synthetic'],['Profile','workspace-capture-v0/1'],['Acquisition','Isolated server browser'],['Requested URL','https://news.example.org/city/riverfront'],['Final URL','Same as requested'],['HTTP status','200 · not a claim about source truth'],['Observed time','2026-11-09T10:43:12Z · server clock'],['Browser claims','None · distinct from future client-claimed browser time'],['Digest','<span class="mono">Illustrative only: 3f12…8a4d (not a verifiable SHA-256)</span>'],['Fidelity','PNG and MHTML; no WARC or trusted timestamp in this V0 record']])}</div>`:tab==='artifacts'?`<div class="pad">${notice('Original bytes are untrusted','App viewing uses inert screenshots and escaped metadata. MHTML is an attachment; never execute it within the Workspace origin.')}${kv([['screenshot.png','Required · stored · 284 KiB'],['page.mhtml',model.state==='partial'?'Required · unavailable':'Required · stored · 742 KiB'],['metadata.json','Required · stored'],['manifest.json','Profile inventory and digests'],['network.warc.gz','Absent for this V0 profile']])}<hr class="divider">${btn('Request private original','download-original','small')}</div>`:`<div class="pad"><ul class="timeline"><li>Editorial revision ${model.revision} saved<small>09 Nov · 10:48 UTC · Alex Morgan</small></li><li>Capture finalized privately<small>09 Nov · 10:43 UTC · immutable bytes</small></li><li>Request admitted with private rationale<small>09 Nov · 10:42 UTC</small></li></ul></div>`}</div></div><div class="stack">${card('Editorial context',`<form id="editorial-form">${field('Collection',`<input name="collection" value="${esc(model.collection)}">`,'Shared grouping, not an ACL.')}${field('Tags',`<input name="tags" value="${esc(model.tags)}">`)}${field('Private editorial note',`<textarea name="note" maxlength="2048">${esc(model.note)}</textarea>`)}<button type="submit">Save new editorial revision</button></form><hr class="divider"><p class="muted">Saving edits invalidates approval for future publication. Existing public projections retain their pinned revision.</p>`)}${card('Review & disclosure',`<p>Review the evidence and the current editorial revision before approving. V0 permits self-review.</p><div class="flex">${btn(model.approved?'Approval recorded':'Approve revision '+model.revision,'approve',model.approved?'':'primary')}${go('Publication preview →','publication')}</div><hr class="divider"><p class="muted">Importance is shared triage only. It does not approve or publish this evidence.</p>`)}${card('Original request context',`${kv([['Collection','Riverfront review'],['Rationale','Preserve the revised review period before the next committee meeting.']])}<hr class="divider"><p class="muted">Immutable private submission context; excluded from default exports and public views.</p>`)}</div></div>`;}
function source(){return head('Source / canonical identity','One source. Every attempt.','Requests are retained even when identical, partial, failed or cancelled. Ordered by server requested_at, then ID.',`${btn('Capture again','new','primary')}${model.stage>=2?btn('Compare selected','compare'):''}`)+(model.state==='empty'?empty('No attempts yet','A source history begins with an admitted capture intent.',btn('New capture','new','primary')):`<div class="card pad"><p class="mono">https://news.example.org/city/riverfront</p><ul class="timeline"><li><div class="flex between"><b>09 Nov · 10:42 UTC — current notice</b>${pill('Complete','good')}</div><small>Server request · cap-0128 · capture observed 10:43 UTC</small><p class="spaced">Review period: 21 days. Editorial status: needs review.</p>${go('Open evidence →','capture')}</li><li><div class="flex between"><b>08 Nov · 15:17 UTC — previous attempt</b>${pill('Identical bytes')}</div><small>Separate request retained; never collapsed into “no record”.</small></li><li><div class="flex between"><b>07 Nov · 11:22 UTC — earlier attempt</b>${pill('Partial','warn')}</div><small>Screenshot retained; required archive unavailable.</small></li><li><div class="flex between"><b>07 Nov · 09:06 UTC — acquisition attempt</b>${pill('Failed','bad')}</div><small>Navigation timeout; not a “source deleted” claim.</small></li></ul></div>${model.stage>=3?notice('Mixed-channel history','Browser observations use server received_at for archive ordering. Client-observed time is separately labeled and never treated as trusted server time.'):''}`);}
function publication(){if(model.role!=='admin')return head('Disclosure / administrator required','Publication preview','Editors may review evidence; V0 publication and revocation require an administrator.')+empty('Administrator action required','The editor role cannot create or revoke a public projection. The server must enforce this independently of the UI.',go('Return to private evidence','capture'));
 if(model.state==='revoked')return head('Disclosure / withdrawn','Publication revoked','Future requests for the old slug and its assets are denied.')+notice('Old public projection withdrawn','Downloaded copies cannot be recalled. Republishing creates a new slug; it does not reactivate the old one.','warn')+btn('Prepare a new projection','new-publication','primary');
 return head('Disclosure / exact snapshot','Review what the public will see.','A public projection freezes an approved editorial revision and an allowed screenshot. Publishing never grants access to private archives.',btn('Return to private evidence','capture'))+`${!model.approved?notice('Approval required','Approve the current editorial revision before publishing. This design lets you perform that step explicitly.','warn'):notice('Revision '+model.revision+' is approved','This preview pins revision '+model.revision+'; later edits cannot silently change an existing public projection.')}<div class="grid cols"><section class="card"><div class="card-head"><h2>Exact public preview</h2>${pill('Not yet published','warn')}</div><div class="image-frame"><img class="evidence-image" src="source-preview.svg" alt="Synthetic screenshot included in the public projection"></div><div class="pad"><h2>Riverfront contract enters a second review period</h2><p class="muted spaced">Original source URL · captured 09 Nov 2026 · screenshot digest and profile label.</p><p>No private notes, rationale, membership, usernames, raw MHTML or export download.</p></div></section>${card('Publication decision',`${kv([['Pinned revision',String(model.revision)],['Audience','Anyone with the resulting URL'],['Included','Screenshot, approved title, source URL, provenance and digest label'],['Excluded','Private editorial/request context and original archives']])}<hr class="divider">${check('I reviewed this exact public projection.','This is separate from approving evidence.',false,'id="publish-consent"')}${btn('Publish this projection','publish','primary',!model.approved?'disabled':'')}<hr class="divider">${model.published?`${pill('Public projection active','good')}<p class="spaced">Existing projection pins revision ${model.publishedRevision}.</p><p>${go('Open synthetic public view →','public')}</p>${btn('Revoke public projection','revoke','danger')}`:'<p class="muted">The real server must recheck role, approval, eligibility and revision at commit.</p>'}`)}</div>`;}
function publicViewer(){if(model.state==='revoked'||model.state==='unavailable')return empty('Evidence unavailable','This link is unavailable. No private record details or withdrawal reason are disclosed.');return `<div class="public-frame">${head('Public evidence / synthetic preview','Preserved source, visible context.','This frozen projection is separate from the private editorial workspace.')}<section class="card"><div class="image-frame"><img class="evidence-image" src="source-preview.svg" alt="Synthetic public evidence screenshot"></div><div class="pad"><h2>Riverfront contract enters a second review period</h2><p class="spaced">Source: https://news.example.org/city/riverfront</p>${kv([['Observed time','09 Nov 2026 · 10:43:12 UTC · server clock'],['Profile','workspace-capture-v0/1'],['Digest','Illustrative placeholder only; no verifiable digest in this mockup'],['Meaning','A capture records what the source presented; it does not certify the truth of its claims.']])}</div></section></div>`;}
function exportScreen(){const prod=model.stage>=1;return head('Evidence / private package','Export a verifiable record','Choose the inventory before generating a package. Exporting does not publish or silently include private context.')+`<div class="grid cols">${card('Package selection',`<form id="export-form">${field('Profile',`<select id="export-profile"><option>${prod?'workspace-export-production/1':'workspace-export-v0/1'}</option></select>`)}${kv([['Evidence','cap-0128 · pinned bytes'],['Required inventory',prod?'PNG, MHTML, WARC, recording metadata, manifest, HTML and required PDF receipt':'PNG, MHTML, metadata, manifest and HTML receipt'],['Compatibility',prod?'New qualified production captures only; this historic V0 capture cannot be relabeled.':'V0 profile identity remains unchanged.']])}<hr class="divider">${check('Include private editorial context','Off by default; explicit disclosure selection.',false,'id="export-private"')}${prod?notice('Historical profile mismatch','This selected record is V0. A production package cannot manufacture its missing WARC. Select a qualified new production capture in the real application.','warn'):check('Request optional PDF receipt','If explicitly requested, missing PDF fails that request. Never silently omit it.')}${btn('Generate synthetic package','generate-export','primary',prod?'disabled':'')}</form>`)}${card('Job & verification',`${model.state==='queued'?`${pill('Queued','teal')}<p class="spaced">Waiting for the shared heavy-work permit. No download is available before finalization.</p>`:model.state==='failed'?notice('Required output failed','No complete package is offered. Retry is explicit; the failed export attempt remains observable.','bad'):model.state==='expired'?notice('Package expired','Original evidence is unaffected. Generate a new export from the pinned eligible inputs.','warn'):`${pill('Preview only')}<p class="spaced">A real completed package includes an independent checksum/inventory verifier and exact provenance labels.</p>`}${kv([['Limit','512 MiB per export'],['Byte access','Authorized, integrity-verified snapshot before success headers'],['Receipt','Controlled escaped model; no archived active HTML'],['Verification','No downloadable evidence package exists in this mockup']])}`)}</div>`;}
function settings(){if(model.role!=='admin')return empty('Administrator access required','Workspace settings and audit are administrative. Host maintenance belongs to a separate operator.');return head('Administration / system status','Keep the evidence service observable.','Configuration values shown here are synthetic. Secrets, captured content and private URLs never belong in telemetry.')+(model.state==='degraded'?notice('Capture worker unavailable','Admission must report the effective state; no “successful capture” is inferred. Check the operator runbook.','warn'):'')+`<div class="grid two">${card('Services & admission',kv([['Application',pill('Available','good')],['PostgreSQL','16 · candidate baseline'],['Capture worker',pill(model.state==='degraded'?'Unavailable':'Available',model.state==='degraded'?'bad':'good')],['Pending queue','3 / 1,000 · 100 positions reserved for interactive admission'],['Heavy work','1 aggregate permit'],['Temp pool','1 GiB shared; per-operation ceilings apply']]))}${card('Backup & maintenance',`${kv([['Last backup','Synthetic · 09 Nov, 02:00 UTC'],['Restore evidence','Not executed by this design artifact'],['Candidate host','Ubuntu 24.04 · Linux x86_64 · 4 CPU / 8 GiB'],['Disk reserve','Greater of 1 GiB or 10%'],['Operator actions','Clean install, backup, restore, upgrade, removal reconciliation']])}<hr class="divider"><p class="muted">Web administrators do not receive host daemon or filesystem control through this screen.</p>`) }${card('V0 membership & admission',`${kv([['Alex Morgan','admin · active'],['Jordan Lee','editor · active'],['Scope','Shared newsroom; collections are not private spaces']])}<hr class="divider">${btn('Preview disabling editor','disable-user','small')}<p class="muted spaced">The real change revokes sessions and evaluates owned jobs/grants. Last-admin recovery is a separate operator procedure.</p>`)}${card('Audit / administrative read',`<ul class="timeline"><li>Editorial revision saved<small>Actor, entity and server time; no note text in event.</small></li><li>Capture finalized<small>Profile, artifact identity and outcome.</small></li><li>Public projection revoked<small>Projection ID and revocation epoch.</small></li></ul>`)}</div>`;}
function admission(){return `<div class="login-frame">${head('Evidence Workspace','A private place for the record.','Sign in with an admitted identity. The server checks provider identity, policy and session state.')}<div class="card pad">${model.state==='expired'?notice('Session expired','Sign in again. A return URL must be local and validated.','warn'):model.state==='provider-error'?notice('Identity provider unavailable','No session was created. Retry explicitly; the failed flow must not loosen admission policy.','bad'):''}<p>GitHub sign-in is selected for V0. Organization admission and individual allowlists are enforced by the service.</p>${btn('Simulate admitted sign-in','signin','primary')}<hr class="divider"><p class="muted">Future U3: optional configured OIDC with explicit account linking. No email-based automatic linking.</p></div></div>`;}
function compare(){return head('C1 / offline derivation','Compare what the source said.','Original artifacts remain unchanged. This is derived text with a reproducible extractor and ordered input pair.',btn('Source history','source'))+`<div class="grid two">${card('Earlier input',`<p><b>cap-0101</b> · 08 Nov · server capture</p>${pill('MHTML supported','good')}<p class="muted spaced">Original digest pinned · extractor text/1</p>`)}${card('Later input',`<p><b>cap-0128</b> · 09 Nov · server capture</p>${pill('MHTML supported','good')}<p class="muted spaced">No live fetch or archived script execution</p>`)}</div><div class="spaced">${model.state==='unsupported'?notice('Input cannot be compared','Unsupported or ambiguous main document. Original evidence remains available; there is no inferred “no change”.','warn'):model.state==='failed'?notice('Analysis failed within its budget','No comparison result is available. Retry or inspect parser diagnostics without exposing source content to telemetry.','bad'):card(model.state==='identical'?'No extracted-text difference':'Text difference / 1 changed passage',`<div class="diff"><span class="context">Committee notice / public review</span>${model.state==='identical'?'<span>Both extracted texts are identical under text/1.</span>':'<span class="minus">− The public review period is 14 days.</span><span class="plus">+ The public review period is 21 days.</span>'}</div><hr class="divider">${kv([['Derivation','Ordered source digests + extractor version + profile fingerprint'],['Meaning','Text difference only; no visual, semantic or truth claim'],['Limits','Offline bounded MHTML parsing; unknown result is not “unchanged”']])}`)}</div>`;}
function investigation(){return head('H1 / anchored context','Keep assertions attached to their source.','Quotes and crops refer to an exact capture, artifact or derivation. Notes never rewrite the evidence.')+`<div class="grid cols"><div class="card"><div class="image-frame"><img class="evidence-image" src="source-preview.svg" alt="Synthetic evidence page for annotation"></div><div class="pad"><p class="eyebrow">Pinned quote / text derivation 1</p><blockquote>“The committee extended the public review period to 21 days.”</blockquote>${model.state==='stale-anchor'?notice('Anchor unavailable','The exact derivation is missing or invalidated. Do not silently reattach this quote to similar current text.','warn'):pill('Exact input pinned','good')}</div></div><div class="stack">${card('Annotation / editorial assertion',`${field('Comment','<textarea>The duration differs from the earlier notice. Check whether the dates also changed.</textarea>')}<p class="muted">Quote spans, crop coordinates and original hashes remain fixed. Editing creates a new annotation revision.</p>${btn('Save annotation revision','save-annotation','primary')}`)}${card('Research task',`${field('Task title','<input value="Verify the revised review dates">')}${kv([['Status','Open'],['Assigned to','Jordan Lee'],['Anchor','cap-0128 / annotation-03']])}<hr class="divider">${check('Task completed','Task state is separate from capture review.')}`)}${card('Saved view',`<p>Riverfront · important · needs review</p>${check('Shared with the newsroom','A saved query is not a snapshot and does not grant access.')}${btn('Save view','save-view','small')}`)}</div></div>`;}
function attention(){return head('C2 / personal attention','Your attention, explicitly managed.','Opening evidence does not acknowledge an event. Shared importance and editorial approval are separate states.')+(model.state==='empty'||model.acknowledged?empty('Nothing waiting for acknowledgement','Acknowledged items remain inspectable. Reopening is an explicit personal action.',btn('Reopen synthetic event','reopen-attention')):card('1 new source-change event',`<div class="flex between"><div><h3>Riverfront notice · extracted text changed</h3><p class="muted">Derived event · cap-0101 → cap-0128 · not a publication or source-truth assertion.</p></div>${pill('Unacknowledged','teal')}</div><div class="flex">${go('Inspect comparison →','compare')}${btn('Acknowledge for me','ack-attention','primary')}</div>`));}
function profiles(){return head('C2 / focus & noise','A transparent view of change.','Immutable comparison profile revisions transform derived text; they never alter captured bytes or source identity.')+`<div class="grid two">${card('Profile revision draft',`${field('Name','<input value="Public notice body">')}${field('Supported text rule','<select><option>Ignore exact lines matching a literal</option><option>Keep lines containing a literal</option></select>')}${field('Literal','<input value="Last updated:">')}${model.state==='invalid'?notice('Rule rejected','Unsupported selectors/regex/active instructions are not accepted by this profile.','bad'):''}<p class="muted">First version: restricted literal text rules. CSS selection and browser interaction recipes remain deferred.</p>${btn('Preview derived result','profile-preview','primary')}`)}${card('Raw / filtered preview',`<div class="diff"><span class="context">Raw: Last updated: 09 Nov</span><br>Filtered: public review period is 21 days.</div><hr class="divider"><p>New revisions receive new fingerprints. Reanalysis of the same bytes is labeled as reprocessing, not a new source-change event.</p>`)}</div>`;}
function search(){return head('H2 / private evidence corpus','Find the passage. See the coverage.','Search indexed evidence text. “No hit” and “not indexed” are different outcomes.')+`<form id="search-form" class="toolbar"><div class="search">${icon('search')}<input id="research-query" aria-label="Search evidence text" value="review period"></div><button class="primary">Search synthetic corpus</button></form><div class="grid cols"><div>${model.state==='no-coverage'?empty('No searchable coverage','The selected artifacts have no supported extraction or have not been indexed. This is not a zero-match result.'):model.state==='no-hits'?empty('No literal matches','Covered: 116 of 128 captures. 12 records remain outside searchable coverage.'):card('1 literal hit',`<p class="eyebrow">cap-0128 / source text derivation</p><p>The committee extended the public <mark>review period</mark> to 21 days.</p><p class="muted">Exact original-text span retained; snippet is escaped and permission checked.</p>${go('Open pinned evidence →','capture')}`)}</div>${card('Research cue',`${field('Literal cue','<input value="review period">')}${check('Case insensitive','Versioned matching policy; not a CSS selector.',true)}${btn('Save cue draft','save-cue','small')}<hr class="divider">${kv([['Indexed','116 / 128 synthetic captures'],['Unsupported','9'],['Pending','3'],['Observations','Email/IP extractors need separate qualification; matches are tentative, not identities.']])}`)}</div>`;}
function reports(){return head('H3 / frozen handoff','Tell the story with exact references.','A report freezes selected revisions and order. It does not expose a live collection or create a public link.')+`<div class="grid cols">${card('Report draft',`${field('Title','<input value="Riverfront review · source chronology">')}${field('Disclosure profile','<select><option>Reference-only report</option><option>Original-evidence report package</option></select>')}<ol><li>cap-0101 · earlier notice · pinned</li><li>cap-0128 · revised notice · pinned</li><li>annotation-03 · revision 1 · editorial assertion</li></ol>${model.state==='missing-input'?notice('Pinned dependency unavailable','Generation is blocked. Do not substitute a latest revision or silently remove missing evidence.','bad'):''}${btn('Preview frozen report','report-preview','primary')}`)}${card('Disclosure preview',`${kv([['Included','Selected titles, citations, explicit annotation revisions'],['Original bytes','Excluded by reference-only profile'],['Private context','Excluded unless specifically selected'],['Audience','Private downloadable package; sharing is a separate human decision'],['Integrity','Input/output inventory, digests and independent verifier']])}<hr class="divider"><p class="muted">Preview, generation, expiry and dependency removal have separate states. A report is not a live saved view.</p>`)}</div>`;}
function transfer(){return head('H4 / native package','Import with quarantine, not inherited trust.','Only the Workspace native transfer profile is supported. Hunchly formats and foreign authority are not imported.')+`<div class="grid two">${card('Quarantined import',`${pill(model.state==='quarantined'?'Anomalies require disposition':'Preview · no records created',model.state==='quarantined'?'warn':'teal')}<p class="spaced">example-case.zip · synthetic fixture · 2 captures</p>${kv([['Original hashes','Preserved as foreign claims until verified'],['Remote identity','Namespaced; not a local user'],['Public links / roles','Never imported'],['Active automation','Never enabled by import'],['Limits','Bounded paths, inventory, nested decoding and quotas']])}<hr class="divider">${btn('Review import disposition','import-preview','primary',model.role==='admin'?'':'disabled')}`)}${card('Selection export',`<p>Choose exact evidence and context revisions. Exporting preserves provenance and labels foreign claims; it grants no publication authority.</p>${btn('Preview native selection','transfer-export')}`)}</div>`;}
function watches(){return head('C3 / opt-in monitoring','Watch a source within a clear budget.','Scheduling is explicit. Failed or blocked captures never replace a meaningful successful baseline.')+`<div class="grid cols">${card('Riverfront notice watch',`${field('Public source URL','<input value="https://news.example.org/city/riverfront">')}${field('Interval','<select><option>Every 24 hours</option><option>Every 1 hour · minimum</option></select>')}${field('Window / time zone','<input value="08:00–18:00 · Europe/London">')}${kv([['State',pill(model.state==='ready'?'Active':model.state==='restore-hold'?'Restore hold':'Paused',model.state==='ready'?'good':'warn')],['Owner','Alex Morgan · active'],['Baseline','cap-0101 · successful HTTP 2xx meaningful text'],['Daily budget','24 attempts/watch · 50 automatic captures total'],['Epoch','7 · stale workers cannot advance it']])}<hr class="divider">${btn(model.state==='ready'?'Pause watch':'Review & explicitly resume',model.state==='ready'?'pause-watch':'resume-watch','primary')}`)}${card('Operational history',`<ul class="timeline"><li>Next due slot<small>10 Nov · 08:00 UTC · no backfill storm.</small></li><li>Baseline preserved<small>Last failed attempt did not overwrite the baseline.</small></li><li>First successful baseline<small>No source-change notification emitted.</small></li></ul><hr class="divider">${model.state==='quota'?notice('Quota exhausted','No new automatic attempt is admitted. The next due slot is evaluated under current limits.','warn'):model.state==='restore-hold'?notice('Restored automation is held','Review owner, destination, scope and baseline before explicit enablement.','warn'):'<p class="muted">Three consecutive qualifying failures pause the watch. Availability and semantic difference are separate signals.</p>'}`)}</div>`;}
function delivery(){return head('C4 / external disclosure','Know what leaves the workspace.','Approved HTTPS destination, explicit owner opt-in and a bounded minimal payload. Delivery is not exactly once.')+`<div class="grid two">${card('Destination & consent',`${kv([['Destination','Newsroom receiver · administrator approved'],['Transport','Versioned restricted HTTPS webhook'],['Owner opt-in','Required separately from destination approval'],['Included','Opaque event ID, event type and minimal safe routing metadata'],['Excluded','Source query, screenshots, notes, raw differences and secret URLs']])}<hr class="divider">${check('Opt in to this approved destination','A server transaction records intent; network delivery happens later.')}${btn('Save delivery intent','save-delivery','primary')}`)}${card('Delivery attempt',`${pill(model.state==='uncertain'?'Acceptance uncertain':model.state==='expired'?'Expired':'Queued',model.state==='ready'?'teal':'warn')}<p class="spaced">${model.state==='uncertain'?'The receiver may have accepted the request before the connection failed. Do not claim non-delivery or automatically create a new intent.':'Finite outbox retries preserve the same intent identity.'}</p>${kv([['Attempts','Maximum 5'],['Lifetime','24 hours'],['Replay','Explicit new action; current authority and disclosure rechecked']])}<hr class="divider">${btn('Review explicit replay','replay-delivery','small')}`)}</div>`;}
function access(){return head('U2 / future access model','Make custody and authority visible.','Each capture belongs to exactly one AccessSpace. Collections remain organizational, within that space.')+`<div class="card pad"><h2>Capability bundles / U1</h2><p class="muted spaced">Multiple explicit bundles; workspace administration alone does not grant content or publication rights.</p><div class="access-grid">${[['Viewer','Read authorized evidence'],['Researcher','Capture and editorial work'],['Reviewer','Approve revisions'],['Publisher','Publish eligible projections'],['Workspace admin','Manage users and configuration']].map(r=>`<div class="access-tile"><b>${r[0]}</b>${r[1]}</div>`).join('')}</div></div><div class="grid two spaced">${card('AccessSpace / Riverfront desk',`${kv([['Custody','Exactly one space per capture'],['Membership','Flat groups and scoped grants'],['Stewards','Explicit membership; maximum 5 per space'],['Existing V0 data','Migrates to shared default; no retroactive privacy claim'],['Move','Controlled preview, publication revocation and generation fences']])}<hr class="divider">${btn('Preview controlled move','move-preview','small')}`)}${card('Lifecycle & federation',`${kv([['Disable user','Revoke sessions/grants; reconcile owned jobs/automation'],['U3 preview',model.stage>=7?'OIDC issuer/subject trust and explicit linking':'Deferred until U3 / 1.6'],['Workload principal','Explicit scoped non-human identity; no publication/admin scope'],['Access review','Check all installed adapters, reports, exports, counts and bytes']])}<hr class="divider"><p class="muted">The V0 role selector is a design tool, not a model of these future bundles. U-stage browser/server tests are still required.</p>`)}</div>`;}
function pairing(){return head('B0 / human approval','Approve only a request you started.','Pairing grants narrow companion actions. It does not grant archive reads, publication or administration.')+`<div class="grid two">${card('Verify the workspace and request',`${model.state==='expired'?notice('Request expired','Begin a new pairing request. Expired approval cannot mint a token.','warn'):model.state==='approved'?notice('Synthetic approval recorded','The real intent may be consumed once. A lost token response requires re-pairing, not secret replay.'):''}${kv([['Origin','https://evidence.example.org'],['Device','Example Chrome · claimed device label, not proof of identity'],['Scopes','B0: collections:read, capture:create, status:own'],['B1/B2','Upload and session scopes need renewed explicit approval'],['Expires','5 minutes from request creation']])}<hr class="divider">${field('Manually enter the code shown by your extension','<input id="pair-code" placeholder="Demonstration: DEMO 42" autocomplete="off">')}${field('Matching phrase','<input id="pair-phrase" placeholder="Demonstration: quiet river">')}${check('The origin, code and phrase match the request I started.','Do not approve an unsolicited request.',false,'id="pair-confirm"')}${btn('Approve pairing request','approve-device','primary',model.state==='expired'?'disabled':'')}`)}${card('Owned devices / revocation',`<p>Example Chrome · Alex Morgan · last activity: synthetic</p><p class="muted">Revocation denies new protected requests, finalization and recording leases. Session storage contains no persistent refresh credential.</p>${btn('Preview device revocation','device-revoke','danger')}`)}</div>`;}
// All actions below change only the synthetic in-memory design model.
document.addEventListener('click', e=>{
 const link=e.target.closest('a[href^="#"]');if(link){e.preventDefault();route(link.getAttribute('href').slice(1));return;}
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(screens[a]){route(a);return;}
 if(a.startsWith('tab-')){model.tab=a.slice(4);render();return;}
 switch(a){
 case 'menu':$('.sidebar').classList.toggle('open');b.setAttribute('aria-expanded',$('.sidebar').classList.contains('open'));break;
 case 'close':closeModal();break;
 case 'importance':model.important=!model.important;render();toast('Shared importance changed. Approval and public projections are unchanged.');break;
 case 'approve':model.approved=true;render();toast('Synthetic revision '+model.revision+' approved. Nothing published.');break;
 case 'publish':if(!model.approved||model.role!=='admin')return;if(!$('#publish-consent')?.checked){toast('Review and confirm the exact projection first.');return;}modal('Publish this exact projection?',`<p>Revision ${model.revision}, the screenshot and selected public metadata will be visible to anyone with the link. Private context and original archives are excluded.</p><p class="muted">Design simulation only; no external publication occurs.</p>`,'confirm-publish','Publish projection');break;
 case 'confirm-publish':closeModal();model.published=true;model.publishedRevision=model.revision;render();toast('Synthetic public projection created.');break;
 case 'revoke':modal('Revoke the public projection?','<p>New requests for its slug and assets will be denied. Previously downloaded copies cannot be recalled.</p>','confirm-revoke','Revoke projection');break;
 case 'confirm-revoke':closeModal();model.published=false;model.state='revoked';render();toast('Synthetic projection revoked.');break;
 case 'new-publication':model.state='ready';render();break;
 case 'csv-preview':model.state='preview';render();break;
 case 'csv-confirm':if(model.state==='queue-full'){toast('No jobs admitted; preserve the preview.');break;}model.submitted=true;route('queue');toast('2 synthetic intents queued atomically.');break;
 case 'cancel-job':modal('Cancel this capture request?','<p>Cancellation is a request. A running attempt must observe a fence; late worker output cannot become accepted evidence.</p>','confirm-cancel','Request cancellation');break;
 case 'confirm-cancel':closeModal();toast('Synthetic cancellation requested. Wait for confirmed terminal state.');break;
 case 'retry-job':model.submitted=true;route('queue');toast('Synthetic retry queued; the prior attempt is retained.');break;
 case 'generate-export':model.state='queued';render();toast('Synthetic export job queued. No package downloaded.');break;
 case 'reset-filters':model.state='ready';render();break;
 case 'download-original':toast('Design only: real downloads require a verified authorized byte snapshot.');break;
 case 'signin':route('dashboard');toast('Synthetic admission; no provider or session contacted.');break;
 case 'ack-attention':model.acknowledged=true;render();toast('Acknowledged for this synthetic user only.');break;
 case 'reopen-attention':model.acknowledged=false;render();break;
 case 'pause-watch':model.state='paused';render();toast('Synthetic watch paused; epoch fenced.');break;
 case 'resume-watch':modal('Resume after review?','<p>Recheck owner, scope, source, quota, baseline and restored hold. No missed work is automatically replayed.</p>','confirm-resume','Resume watch');break;
 case 'confirm-resume':closeModal();model.state='ready';render();break;
 case 'approve-device':if($('#pair-code')?.value.trim()!=='DEMO 42'||$('#pair-phrase')?.value.trim()!=='quiet river'||!$('#pair-confirm')?.checked){toast('Manually enter the matching demonstration code and phrase, then confirm.');break;}model.state='approved';render();toast('Synthetic pairing approval only; no credential issued.');break;
 case 'device-revoke':modal('Revoke this companion?', '<p>New requests and finalization lose authority. Recording stops; local pending bytes require deliberate review or discard.</p>','close','Close preview');break;
 case 'disable-user':modal('Preview user disablement','<p>Real execution revokes sessions/grants and reconciles owned work. This design performs no user-management request.</p>','close','Close preview');break;
 case 'move-preview':modal('Controlled custody move','<p>Requires the specified grants in both spaces, exact dependency closure and revocation of affected public projections. No copy is created by this preview.</p>','close','Close preview');break;
 default:toast('Synthetic design preview only. The implementation plan defines the required contract and qualification gate.');
 }
});
document.addEventListener('change', e=>{if(e.target.id==='stage'){model.stage=Number(e.target.value);if(screens[screen].stage>model.stage){screen='dashboard';location.hash=screen;}model.state='ready';render();}if(e.target.id==='state'){model.state=e.target.value;render();}if(e.target.id==='role'){model.role=e.target.value;render();}if(e.target.id==='archive-filter')filterArchive();});
function filterArchive(){const term=$('#archive-search')?.value.toLowerCase() || '';const important=$('#archive-filter')?.value==='important';const rows=fixtureRows.filter((r,i)=>(!important||(i===0&&model.important))&&`${r[0]} ${r[1]}`.toLowerCase().includes(term));$('#archive-table').innerHTML=rows.length?tableRows(rows):'<div class="empty"><h2>No matching evidence</h2><p>Clear a filter to inspect other synthetic records.</p></div>';}
document.addEventListener('input',e=>{if(e.target.id==='archive-search')filterArchive();});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='capture-form'){if(model.state==='queue-full'||model.state==='offline'){toast('No job accepted. Your draft remains visible.');return;}const u=$('#capture-url').value;try{const parsed=new URL(u);if(!['http:','https:'].includes(parsed.protocol)||parsed.username||parsed.password||['localhost','127.0.0.1','[::1]'].includes(parsed.hostname))throw Error('invalid');}catch{model.state='invalid';render();return;}model.submitted=true;model.important=$('#new-important').checked;route('queue');toast('Synthetic request queued privately; no URL fetched.');}else if(e.target.id==='editorial-form'){if(model.state==='conflict'){toast('Newer revision exists; edits were not applied.');return;}const data=new FormData(e.target);model.collection=data.get('collection');model.note=data.get('note');model.tags=data.get('tags');model.approved=false;model.revision+=1;render();toast('Synthetic editorial revision saved. Approval invalidated; evidence bytes unchanged.');}else if(e.target.id==='search-form'){toast('Synthetic search: one fixture result; no live index queried.');}});
$('#theme').addEventListener('click',()=>{document.body.classList.toggle('dark');render();});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(screens[next]&&next!==screen)route(next);});
render();
